from pathlib import Path
import base64
root=Path.cwd()
out=root/'artifacts/instagram'
def data(path,mime): return 'data:'+mime+';base64,'+base64.b64encode((root/path).read_bytes()).decode()
fonts=''
for name,path,weight in [('Geist','node_modules/geist/dist/fonts/geist-sans/Geist-Variable.woff2','100 900'),('Manrope','node_modules/@fontsource/manrope/files/manrope-latin-800-normal.woff2','800'),('Inter','node_modules/@fontsource/inter/files/inter-latin-400-normal.woff2','400'),('Inter','node_modules/@fontsource/inter/files/inter-latin-600-normal.woff2','600'),('Orbitron','node_modules/@fontsource/orbitron/files/orbitron-latin-500-normal.woff2','500')]:
 fonts+=f'@font-face{{font-family:{name};src:url("{data(path,"font/woff2")}");font-weight:{weight};}}'
wing=data('public/brand/wing.png','image/png')
word=data('public/brand/kosifly-logo-text.png','image/png')
